-- Form validation checks (rows with passed = FALSE fail)
CREATE OR REPLACE VIEW arf210_1b_checks AS
  SELECT '6.2.3>=0' AS check_id, 'ERROR' AS severity, 'Collateral-swap CLF adjustment must be entered as zero if negative' AS description, (((c_6_2_3__amount) >= (CAST(0 AS DECIMAL(38, 10))))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '6.4<=6.1' AS check_id, 'ERROR' AS severity, 'CLF securities maturing <= 30 days cannot exceed item 6.1' AS description, (((c_6_4__amount) <= (c_6_1__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '9.2.1<=9.2' AS check_id, 'ERROR' AS severity, 'Intra-group ''of which'' exceeds item 9.2' AS description, (((c_9_2_1__amount) <= (c_9_2__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '9.4.1<=9.4' AS check_id, 'ERROR' AS severity, 'Intra-group ''of which'' exceeds item 9.4' AS description, (((c_9_4_1__amount) <= (c_9_4__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '9.5.1<=9.5' AS check_id, 'ERROR' AS severity, 'Intra-group ''of which'' exceeds item 9.5' AS description, (((c_9_5_1__amount) <= (c_9_5__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '11.1.1<=11.1' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 11.1' AS description, (((c_11_1_1__amount) <= (c_11_1__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '19.1.1.1<=19.1.1' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 19.1.1' AS description, (((c_19_1_1_1__amount) <= (c_19_1_1__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '11.2.1<=11.2' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 11.2' AS description, (((c_11_2_1__amount) <= (c_11_2__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '19.1.2.1<=19.1.2' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 19.1.2' AS description, (((c_19_1_2_1__amount) <= (c_19_1_2__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '11.3.1<=11.3' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 11.3' AS description, (((c_11_3_1__amount) <= (c_11_3__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '19.1.3.1<=19.1.3' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 19.1.3' AS description, (((c_19_1_3_1__amount) <= (c_19_1_3__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '11.4.1<=11.4' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 11.4' AS description, (((c_11_4_1__amount) <= (c_11_4__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '19.1.4.1<=19.1.4' AS check_id, 'ERROR' AS severity, '''of which'' exceeds item 19.1.4' AS description, (((c_19_1_4_1__amount) <= (c_19_1_4__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '11.7 of-which' AS check_id, 'ERROR' AS severity, '''of which'' rows exceed item 11.7' AS description, (((((((((c_11_7_1__amount) + (c_11_7_3__amount))) + (c_11_7_5__amount))) + (c_11_7_7__amount))) <= (c_11_7__amount))) AS passed FROM arf210_1b_wide
UNION ALL
  SELECT '20.7-20.9<=20' AS check_id, 'ERROR' AS severity, 'Intra-group inflows exceed item 20' AS description, (((((((c_20_7__amount) + (c_20_8__amount))) + (c_20_9__amount))) <= (c_20__amount))) AS passed FROM arf210_1b_wide;
